INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (2, 'Energia', 'Calendario Cholquij', 'Elementos', '<p>El calendario Cholq\'ij utiliza las energías del 1 al 13 pero su ciclo es de meses y días.</p>

<p> La relación del 13 con los ciclos de la vida es múltiple, entre ellas se pueden mencionar:</p>
<ul>
	<li>Las 13 energías en el nacimiento</li>
	<li>Los 13 ciclos de 20 días de un año Cholq’ij.</li>
</ul>
<p>
El 13 es una cantidad importante en el pensamiento maya. Se utiliza para indicar el nivel de
energía y al combinar con el significado de los nawales construye la personalidad.		Este número
tiene influencia en toda la vida, marca la niñez, juventud, madurez y ancianidad.
</p>
', '<p>The Cholq\'ij calendar uses energies from 1 to 13, but its cycle consists of months and days.</p>

<p>The relationship of 13 with the cycles of life is manifold, among them can be mentioned:</p>
<ul>
    <li>The 13 energies at birth</li>
    <li>The 13 cycles of 20 days in a Cholq\'ij year.</li>
</ul>

<p>Thirteen is an important quantity in Mayan thought. It is used to indicate the level of energy and when combined with the meaning of the nawales, it constructs personality. This number influences all of life, marking childhood, youth, maturity, and old age.</p>', '<p>Cholq\'ij k\'ajkunab\'ij re ru k\'iche\' pa q\'ij aj q\'ij re li\', xan xatz\'ib\'ij ri ajawab\' re li.</p>

<p>Ri\' 13 chi xan q\'ijab\' ru re ronojelaj kajibalaj, xan chi\' chwe ri:</p>
<ul>
    <li>Ri\' 13 k\'ajkunab\' k\'ichpanik</li>
    <li>Ri\' 13 kajibalaj chi 20 q\'ij re Cholq\'ij winaq.</li>
</ul>

<p>Ri\' 13 chi chi\' re ri Jun ulew ri k\'iche\'. Xan chwe ri k\'ajkunab\' re ri nawales, xan xkib\'ab\'ij re aatinamit re. Ri ronojelaj kajibalaj chi konojelaj, xan ka\'nin, xapalaj, kiq\'ajil, xan ruk\'uxaj.</p>', '<p>Ri q’ijob’äl Cholq\'ij xub’ij ruwäch ri k’aslem pa ri’ jun chikaxik b’i’aj 1 pa 13 chawe runuk’ k’ak’a’ taq tz’ijöj k’aslem rech ulew.</p>

<p> Ri nab’eyal xub’ij 13 chi ri k’aslem rech qak’aslem b’anwa’ jun ik’ütal, rumal xatz’e jun paq’orb’äl:</p>
<ul>
<li>Ri 13 ch’ob’äl pa ri ala’</li>
<li>Ri 13 tz’ijöj rech wuj q’iij taq 20 k’aslem junab’ Cholq’ij</li>
</ul>
<p>
Ri jun 13 jun ch’ob’äl k’aslem pa ri Maya’ qatzij. Xub’ij chi ruq’a’ k’aslem chikaxik jun ch’ob’äl pa junal
nawal rumal xk’olb’e’ jun taqanel. Ri junab’ xub’ij qak’aslem, xub’ij chub’än chi ri ala’, yo’kom, xe’ k’axik, e k’ay taq ch’ab’.
</p>
', '<p>Le calendario Cholq\'ij ku ts\'o\'ok le yáantajo\'ob tu 1 ti\' 13 pero u ciclo es jump\'éel u k\'iino\'ob yéetel u k\'iino\'ob.</p>

<p> Le relación le 13 yéetel le ciclos tu kuxtal es múltiple, ti\' jump\'éel u k\'a\'ato\'ob:</p>
<ul>
<li>Le 13 yáantajo\'ob tu k\'i\'ix</li>
<li>Le 13 ciclos tu 20 k\'iino\'ob tu jump\'éel ja\'ab Cholq’ij</li>
</ul>
<p>
Le 13 es jump\'éel cantidad importante tu ts\'ookbilil maya. Ku t\'aano\'ob u k\'iin tu yáantaj le nivelil u 
yáantaj yéetel ku t\'aano\'ob yéetel le significado le nawales ku t\'aan yéetel ku yaantal u máak\'. Le número 
ya\'abil u yáantaj tu jump\'éel kuxtal, ku ts\'a\'abal le chi\'ich, ka\'ansaj, ka\'anal yéetel nojoch ka\'anal.
</p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (0, 'Forma de Contar', 'Calendario Cholquij', 'Informacion', '<h2>Forma de contar</h2>
<p> Una manera de contar el Cholq’ij para los maya k’iche’ de la actualidad es iniciar el conteo en Waqxaqib’ B’atz’ (8 B’atz’), repitiendo así cada 260 días ese número y fecha (Aj Xol Ch’ok, 2008). Cada día del calendario se combina con un numeral que va del 1 al 13, hasta completar 260 días. El mismo día en que inicia la cuenta vuelve a repetirse cada 260 días. En la antigüedad se acostumbraba a empezar el calendario en 1 Imox y se seguía el mismo proceso de multiplicación de los numerales con los días para alcanzar el total de 260 (Aj Xol Ch’ok, 2008). La construcción del ciclo de 260 días del calendario Cholq’ij tiene como base la disciplina vigesimal maya (13X20); “esta relación organiza una frecuencia matemática del movimiento natural lunar de 13:20 que se determina en base a las gravitaciones, principalmente de la Luna–Tierra, las cualidades del ser en la madre Tierra de acuerdo a su día de engendración, día del nacimiento y su proyección o misión en la vida” (García, Curruchiche & Taquirá, 2009, p. 234). Los días de este calendario “son representados también en los 10 dedos superiores de las manos, más los 10 dedos inferiores de los pies, lo que suma 20, que representa los días del Cholq’ij”, pues la construcción matemática del sistema vigesimal maya “se fundamenta en el Jun Winaq de 20 dedos” (García, Curruchiche & Taquirá, 2009, p. 47 y 234).</p>
', '<h2>Way of Counting</h2>
<p>One way to count the Cholq’ij for present-day Maya K\'iche\' is to start the count on Waqxaqib’ B’atz’ (8 B’atz’), thus repeating every 260 days that number and date (Aj Xol Ch’ok, 2008). Each day of the calendar is combined with a numeral ranging from 1 to 13, until reaching a total of 260 days. The same day the count begins repeats every 260 days. In ancient times, it was customary to start the calendar on 1 Imox and follow the same process of multiplying the numerals with the days to reach the total of 260 (Aj Xol Ch’ok, 2008). The construction of the 260-day cycle of the Cholq’ij calendar is based on the Mayan vigesimal discipline (13X20); "this relationship organizes a mathematical frequency of the natural lunar movement of 13:20 determined based on gravitations, mainly from the Moon-Earth, the qualities of being in Mother Earth according to its day of conception, day of birth, and its projection or mission in life" (García, Curruchiche & Taquirá, 2009, p. 234). The days of this calendar "are also represented on the 10 upper fingers of the hands, plus the 10 lower fingers of the feet, which adds up to 20, representing the days of the Cholq’ij", as the mathematical construction of the Mayan vigesimal system "is based on the Jun Winaq of 20 fingers" (García, Curruchiche & Taquirá, 2009, p. 47 and 234).</p>', null, '<h2>Ri Uwachib’il</h2>
<p> Jun k’ak’a’ utz’ib’äl ri q’ijob’äl Cholq’ij chike ri maya k’iche’ wachib’äl xuquje’ xul pe ruk’ ri Waqxaqib’ B’atz’ (8 B’atz’), tziya’ chi utz’ k’a ri tz’ib’äl xpe jun b’elejeb’ tz’ijöj (Aj Xol Ch’ok, 2008). Jun chikaxik ri q’ij pa q’ijob’äl xub’an jun ruk’ k’aslem chike 1 pa 13, chi xpe ri b’elejeb’ tz’ijöj. Ri jun q’ij xpe pe chi k’a jun chikaxik chi jun b’elejeb’ tz’ijöj. Pa ri e qama’ chik xq’a jun chi jun q’ij pa 1 Imox xa xe ruk’ jun chikaxik pa utz’ib’äl chi jun tz’iib’ej b’a q’ij ri xpe jun b’elejeb’ tz’ijöj (Aj Xol Ch’ok, 2008). Ri utz’ib’äl jun chikaxik jun b’elejeb’ tz’ijöj pa ri q’ijob’äl Cholq’ij xub’ij pa k’aslem chikij ri mayab’ pa utz’ib’äl (13X20); “ri nab’eyal xub’ij jun k’aslem saqirkachoqil ri ruk’ jun pa jun chi’ k’aslem ri ya’ ri 13:20 ri xub’ij pa ruk’ jun xna’oj, chuqa’ ri yuwe’ ri’ ch’ab’, ri’ ri ch’akul ri’ rech qa ch’ab’ pa ri ch’ab’il ri ruka’ jun chikaxik, jun q’ij pa q’ij ri’ xub’ij ruk’ pa jun b’anab’il richin qak’aslem” (García, Curruchiche & Taquirá, 2009, p. 234). Ri q’ijob’äl pa ri q’ijob’äl xub’an pa ri 10 ruxo’chi’ ri saqi’ wachb’il, k’a ri 10 ruxo’chi’ ri saqi’ xak’ab’il, ri’ chi pa jun jun b’anab’il ri’ xub’an jun q’ijob’äl Cholq’ij”, rumal ri utz’ib’äl jun b’anab’il richin jun utz’ib’äl ri mayab’ xub’ij pa Jun Winaq ri 20 ruxo’chi’ (García, Curruchiche & Taquirá, 2009, p. 47 y 234).</p>
', '<h2>Forma de contar</h2>
<p> Jump’éel manera tu ts\'ook le Cholq’ij ti’ le maya k’iche’ tu k’iino’ob es in k’a’ato’ tu Waqxaqib’ B’atz’ (8 B’atz’), ts’ook u ts’ook tu jump’éel 260 k’iino’ob u número yéetel le k’iin (Aj Xol Ch’ok, 2008). Jump’éel k’iin le calendario ku ts’ook u ts’a’bal tu jump’éel número ku xíimbal ti’ 1 ti’ 13, tu ts’a’bal u 260 k’iino’ob. Le jump’éel k’iin tu ka’anal le cuenta ku ya’abil u ts’ook tu jump’éel 260 k’iino’ob. Tu nojoch ka’analil ku xíimbal tu in k’a’ato’ le calendario tu 1 Imox yéetel ku ts’ook u mismo proceso tu yáantaj u número yéetel le k’iino’ob tu ts’a’bal u 260 (Aj Xol Ch’ok, 2008). Le nojoch ts’ookil le ciclo 260 k’iino’ob le calendario Cholq’ij ku t’aano’ob tu disciplina vigesimal maya (13X20); “le relación ku nojoch tu yáantaj matemática tu k’iinil u nojoch 13:20 ku ya’abil tu yáantaj u gravitacióno’ob, ti’ nojochil le Nojoch K’iin–Lu’um, le ku ts’ookil le máak’ tu Nojoch Lu’um ti’ u k’iino’obil tu k’iino’obil u nojoch, k’iinil u ya’abil yéetel le proyecto o misión tu kuxtal” (García, Curruchiche & Taquirá, 2009, p. 234). Le k’iino’ob le calendario “ku t’aano’ob xan tu 10 mejen yéetel ku 10 mejen yéetel ku nojoch k’iin, ku ts’ook 20, ku t’aano’ob le k’iino’ob le Cholq’ij”, tu ya’abil matemática le sistema vigesimal maya “ku t’aano’ob tu Jun Winaq le 20 mejen” (García, Curruchiche & Taquirá, 2009, p. 47 y 234).</p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (0, 'Informacion', 'Calendario Cholquij', 'Informacion', '<p>El Cholq´ij deriva su nombre de los términos maya-k´iche´:</p><ul><li>Chol: Contar cosas puestas en orden</li><li>Q´ij: el sol o día</li></ul><p>El Cholq’ij es un calendario sagrado del pueblo Maya, compuesto por 260 días divididos en 13 meses. También recibe el nombre de calendario ritual o calendario sagrado o Tzolkin (Barrios, 2004; García, Curruchiche & Taquirá, 2009; Aj Xol Ch’ok, 2008; Rupflin, 1999).</p><p>“El Cholq´ij es uno de los instrumentos que los Abuelos del Pueblo maya crearon; tiene dos aplicaciones principales, la primera: ubica momentos para actividades colectivas; la segunda: tiene una aplicación individual para identificar la conducta natural o la forma de ser de las personas por medio de su nawal, es decir, los rasgos psicológicos básicos, positivos y negativos.</p><p>Este calendario fue configurado a partir de los movimientos que la Luna realiza en su órbitta alrededor de la Tierra. Así como el calendario AB’ agrícola o solar de 365 días está configurado en base al movimiento de traslación de la Tierra alrededor del Sol y es identificado como energía masculina.</p><p>Por otra parte, el Choloq’ij o calendario sagrado es considerado energía femenina, por su relación con los movimientos de la Luna y por la influencia que este cuerpo celeste ejerce sobre los organismos femeninos de la naturaleza y los seres humanos.”</p><h2>Forma de contar</h2><p>Una manera de contar el Cholq’ij para los maya k’iche’ de la actualidad es iniciar el conteo en Waqxaqib’ B’atz’ (8 B’atz’), repitiendo así cada 260 días ese número y fecha (Aj Xol Ch’ok, 2008). Cada día del calendario se combina con un numeral que va del 1 al 13, hasta completar 260 días. El mismo día en que inicia la cuenta vuelve a repetirse cada 260 días. En la antigüedad se acostumbraba a empezar el calendario en 1 Imox y se seguía el mismo proceso de multiplicación de los numerales con los días para alcanzar el total de 260 (Aj Xol Ch’ok, 2008). La construcción del ciclo de 260 días del calendario Cholq’ij tiene como base la disciplina vigesimal maya (13X20); “esta relación organiza una frecuencia matemática del movimiento natural lunar de 13:20 que se determina en base a las gravitaciones, principalmente de la Luna–Tierra, las cualidades del ser en la madre Tierra de acuerdo a su día de engendración, día del nacimiento y su proyección o misión en la vida” (García, Curruchiche & Taquirá, 2009, p. 234). Los días de este calendario “son representados también en los 10 dedos superiores de las manos, más los 10 dedos inferiores de los pies, lo que suma 20, que representa los días del Cholq’ij”, pues la construcción matemática del sistema vigesimal maya “se fundamenta en el Jun Winaq de 20 dedos” (García, Curruchiche & Taquirá, 2009, p. 47 y 234).</p>', '<p>The Cholq´ij derives its name from the Maya-K´iche´ terms:</p>
<ul>
	<li>Chol: Counting things placed in order</li>
	<li>Q´ij: the sun or day</li>
</ul>

<p>The Cholq’ij is a sacred calendar of the Maya people, consisting of 260 days divided into 13 months. It is also known as the ritual calendar or sacred calendar or Tzolkin (Barrios, 2004; García, Curruchiche & Taquirá, 2009; Aj Xol Ch’ok, 2008; Rupflin, 1999).</p>

<p>“The Cholq´ij is one of the instruments that the Grandparents of the Maya People created; it has two main applications, the first: locating moments for collective activities; the second: it has an individual application to identify the natural behavior or the way of being of people through their nawal, that is, the basic, positive and negative psychological traits.</p>

<p>This calendar was configured based on the movements that the Moon makes in its orbit around the Earth. Just as the AB\' agricultural or solar calendar of 365 days is configured based on the Earth\'s translational movement around the Sun and is identified as masculine energy.</p>

<p>On the other hand, the Choloq’ij or sacred calendar is considered feminine energy, due to its relationship with the movements of the Moon and the influence that this celestial body exerts on the female organisms of nature and humans.”</p>', '<p>Cholq´ij ri\' chi\' na\' ri maya-k´iche´ chi´:</p>
<ul>
	<li>Chol: Ri\' k\'ajkunab\' k\'iche\' chuqaqilaj</li>
	<li>Q´ij: ri ronojelaj q\'ij</li>
</ul>

<p>El Cholq’ij k\'u k\'ajlal winaq ri ri\' maya, k\'u chwe ri 260 ronojelaj chi\' k\'u chwe. Xkib\'ij chi\' k\'ajkunab\' k\'iche\' k\'uj winaq k\'ajlal winaq, wuj winaq k\'ajlal winaq k\'ij winaq k\'utu\'un (Barrios, 2004; García, Curruchiche & Taquirá, 2009; Aj Xol Ch’ok, 2008; Rupflin, 1999).</p>

<p>“El Cholq´ij k\'u k\'ajlal kaj chikawil ri ri\' ulew maya, chikawil chwe ri jun kub\'ij ri\', kaj konojelaj kajibalaj re ru\' chikawil winaq re k\'iche\', xkib\'ij chawal ri\': k\'u nimalaj ri chikawil winaq; kaj winaq k\'ajlal kajibalaj re konojelaj chikawil ri kaj.</p>

<p>Chi\' ri\' k\'ajkunab\' chikawil kib\'ij chi\' na\' re ruq\'ij kib\' chi\' Q\'ij chik\'ut ri k\'u\'xajik ri ruk\'uxik chik\'ut xq\'ij, xq\'ij kib\'ij k\'ij ronojelaj k\'ij, k\'ajibalaj konojelaj.</p>

<p>Ri jun konojelaj, ri Choloq’ij k\'u k\'ajlal q\'ij kajibalaj kub\' re konojelaj, xchawe xq\'ij k\'ij chik\'ut ch\'aj juyub\' chik\'ut konojelaj xq\'ij k\'ij k\'aj chik\'ut kub\'.</p>
', '<p>
El Cholq´ij xub’anik pa ri saq tzij ri maya-k´iche´:
<ul>
<li>Chol: Utz’ib’an taq b’anob’ chike jun na’oj</li>
<li>Q´ij: Ri q’ij pa ri q’ij</li>
</ul>
</p>

<p> Ri Cholq’ij jun k’ak’a’ q’ijob’äl chike ri ch’ab’il Maya, xub’ij chi jun junab’ k’aslem chike jun b’elejeb’ q’ij chi xkix na jun k’ak’a’. Xa xa jun taqib’äl ruk’a jun q’ijob’äl rech k’aslem chike jun b’elejeb’ q’ij xub’anik taq ri’ chi jun kal. Ri Cholq’ij xub’an chi k’ak’a’ jun ch’ab’il richin jun taqib’äl richin ch’ab’il chike Tzolkin (Barrios, 2004; García, Curruchiche & Taquirá, 2009; Aj Xol Ch’ok, 2008; Rupflin, 1999).</p>

<p>“Ri Cholq´ij jun taqib’äl ri xk’ul chi ri Ajaw rech ri ch’ab’il maya xutz’ub’ chike; pa junb’ey junab’ ri’ xub’ij jun kaqib’äl jun k’ak’a’ richin jun k’aslem; ri junab’ xub’ij k’aslem chike jun ch’akul; junab’ xub’ij jun taqib’äl rech junq’ij ri utz’ib’äl chi jun chi ruk’a’ ch’akul, chike jun nawal, xub’ij jun qak’aslem chiq’a jun, jun nab’eyal pa jun chikaxik, jun k’aslem chikaxik.”</p>

<p>Ri jun q’ijob’äl xub’anik chi jun tzij ri’ ri xub’ij chi ri q’ij pa jun chikaxik pa ri’ ri xe’ chi q’ij pa ri ch’ab’il ri xkiwach chi jun junab’ wachib’il chi k’aslem chike ri ajaw xak’ab’il pa ri ch’ab’il jun k’ak’a’ pa jun ch’ab’il pa 365 q’ij xub’anik chi jun junab’ k’aslem chi ri q’ij pa jun taqib’äl ri xub’an chi jun q’ij ri xutik xib’an chi jun nab’eyal chik pa k’aslem. Ri’ xub’ij chi ri jun q’ijob’äl AB’ jun q’ijob’äl rech xutik pa ch’ab’il chike jun k’aslem pa ri k’aslem, pa ri ch’ab’il xax q’ijob’äl jun utz’ib’äl richin ch’akul qitzij chi ri k’aslem chike jun na’oj. </p>

<p> Ri Cholq’ij chike jun q’ijob’äl ch’ab’il xub’ij jun k’aslem chi k’aslem jun ch’akul pa qitzij chi ri k’aslem, ri’ xub’ij chi jun q’ijob’äl jun k’ak’a’ rech ch’akul chike ri k’aslem chike jun k’aslem chike ri jun utz’ib’äl chikaxik jun ch’ab’il pa ch’akul, chike jun ajaw ri xub’an pa ri k’aslem chike jun chikaxik.”
</p>
', '<p>
El Cholq\'ij deriva su nombre de los términos maya-k’iche’:
<ul>
<li>Chol: Ts’ook le ba’ax ku ya’abil tu nojoch</li>
<li>Q’ij: le k’iin o k’iinil</li>
</ul>
</p>

<p> Le Cholq’ij es jump’éel calendario nojoch le máak’ab Maya, ku ya’abil tu 260 k’iino’ob ku ts’o’ok tu 13 meses. Bey xan ku t’aano’ob jump’éel calendario ritual o calendario nojoch o Tzolkin (Barrios, 2004; García, Curruchiche & Taquirá, 2009; Aj Xol Ch’ok, 2008; Rupflin, 1999).</p>

<p>“Le Cholq’ij es jump’éel le ba’ax le Nojoch Máak’ab le máak’ab ku ya’abil; yaan jump’éel ka’analil ku beetik, le yáaxil: ku ts’ook u k’iinil yéetel jump’éel tu tsikbal; le ka’a: yaan jump’éel yáantaj ti’ u ka’analil ku ya’abil u k’iin yéetel u ya’ab jump’éel máak’ab ku ka’anal tu ya’ab jump’éel, u yáanal le ku nojoch máako’ob, le ts’o’okil tsikbalil, ts’ookilil yéetel ma’ nojoch.</p>

<p>Le calendario ku ya’abil tu yáantaj le ka’analil u k’iinil le Nojoch ku ximbal ti’ u yóok’ol le Nojoch Lu’um tu yóok’ol Nojoch Lu’um. Bey xan le calendario AB’ nojochil o k’iinil de 365 k’iino’ob ku ya’abil tu yáantaj le ka’analil u ximbalil le Nojoch Lu’um tu yóok’ol le K’iin yéetel ku t’aano’ob le kuxtalil masculino.</p>

<p>Tu láak’, le Cholq’ij o calendario nojoch ku ya’abil ku t’aano’ob kuxtalil femenino, le ba’ax ku yáantaj le ka’analil le Nojoch yéetel le ts’a’abal ku ya’abil ku ya’abil ti’ le máako’ob femeninos tu yóok’ol k’iin yéetel le máak’ab.”
</p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (0, 'Informacion', 'Calendario Haab', 'Informacion', '<p>El calendario solar maya, llamado Haab\', es una cuenta de 365 días y por lo tanto se aproxima al año solar es el calendario civil, agrícola Maya, es el calendario de los reyes Mayas.</p>    <p>La palabra <strong> "HAAB\'" </strong> significa <strong> "AÑO" </strong> en el idioma maya yucateco.</p>    <p>El Haab está compuesto por 18 meses de 20 días cada uno, más un mes que consta de 5 días. Cada mes de 20 días, conocido como uinal, tiene su propio nombre. Todos estos 18 meses juntos suman 360 días.</p>    <p>El último mes, compuesto de 5 días, se conoce como Wayeb. Los 19 meses en su totalidad suman 365 días.</p>    <p><strong>18 x 20 + 5 = 365 </strong></p>    <p> </p>    <figure class="easyimage easyimage-full"><img alt="" src="../imgs/Calendario Haab/0.jpeg" width="300" />  <figcaption></figcaption>  </figure>    <p>Fue elaborado por los astrónomos y matemáticos Mayas para dar respuesta a la necesidad de las personas para su abastecimiento de alimento con la siembra y cosecha del sagrado maíz, el frijol, y toda clase de productos agrícolas indispensable para la buena alimentación del ser humano; y en la necesidad de establecer el tiempo de duración del mando y cambio de autoridades imperiales, comunales y civiles del pueblo.</p>    <p>Este calendario, según los expertos, se estima que se utilizó por primera vez alrededor del solsticio de invierno de 550 ANE (Antes de Nuestra Era) y fue creado para ser utilizado en conjunto con el <strong> Tzolkin </strong>. En operación conjunta, el <strong> Haab </strong> y el <strong> Tzolkin </strong> crean un ciclo más grande de 52 años llamado como la <strong> Rueda Calendárica </strong> o <strong> Calendario Redondo</strong> que fue utilizado no solo por los mayas sino también por el resto de las culturas en Mesoamericanas.</p>    <p> </p>    <h3>Utilidad</h3>    <hr />  <p>El calendario <strong> Habb\' </strong> sirve para el control de los fenómenos astronómicos y estacionales del año solar como lo son:</p>    <ul>  <li>Equinoccios</li>  <li>Solsticios</li>  </ul>    <p>También sirve para el establecimiento de nuevas autoridades de los pueblos, marca los ritos ceremoniales colectivos y las temporadas para la siembra de cultivos, aparte de definir el temperamento de las personas de acuerdo a la fecha de su nacimiento</p>    <h3>Exactitud</h3>    <hr />  <p>Debido a que el tiempo real que tarda nuestro Sol en reaparecer exactamente en las mismas posiciones que se ve desde la Tierra es un poco más largo que 365 días (365.2421897 días), se necesitan ajustes periódicos para mantener una acumulación de los recuentos anuales del calendario en alineación con la Tierra girando alrededor del sol.</p>    <p>Los antiguos mayas abordaron este problema de manera diferente a lo que hacemos hoy. En lugar de agregar un año bisiesto cada 4 años, restaron 13 días cada 52 años.</p>    <p>Es muy interesante saber que el calendario Haab\' tiene un error de solo 1 día en 6729 años, mientras que nuestro calendario “moderno” tiene un error de solo 1 día en 3236 años.</p>   ', '<p>The Maya solar calendar, called Haab\', is a count of 365 days and therefore approximates the solar year. It is the civil, agricultural calendar of the Maya, and it is the calendar of the Mayan kings.</p>
<p>The word <strong>"HAAB\'"</strong> means <strong>"YEAR"</strong> in the Yucatec Maya language.</p>
<p>The Haab\' consists of 18 months of 20 days each, plus a month consisting of 5 days. Each 20-day month, known as a uinal, has its own name. All of these 18 months together add up to 360 days.</p>
<p>The last month, composed of 5 days, is known as Wayeb. The 19 months in total add up to 365 days.</p>
<p><strong>18 x 20 + 5 = 365 </strong></p>
<figure class="easyimage easyimage-full"><img alt="" src="../imgs/Calendario Haab/0.jpeg" width="300" /><figcaption></figcaption></figure>
<p>It was elaborated by Maya astronomers and mathematicians to respond to people\'s need for food supply with the planting and harvesting of sacred corn, beans, and all kinds of agricultural products indispensable for human nutrition, as well as the need to establish the duration of imperial, communal, and civil authorities\' rule and change.</p>
<p>According to experts, this calendar is estimated to have been used for the first time around the winter solstice of 550 BCE (Before Common Era) and was created to be used in conjunction with the <strong>Tzolkin</strong>. In joint operation, the <strong>Haab</strong> and the <strong>Tzolkin</strong> create a larger cycle of 52 years called the <strong>Calendar Round</strong> or <strong>Round Calendar</strong>, which was used not only by the Maya but also by the rest of the cultures in Mesoamerica.</p>
<h3>Utility</h3>
<hr />
<p>The <strong>Haab\' calendar</strong> serves for the control of astronomical and seasonal phenomena of the solar year such as:</p>
<ul>
<li>Equinoxes</li>
<li>Solstices</li>
</ul>
<p>It also serves for the establishment of new authorities of the towns, marks the collective ceremonial rites and the seasons for crop planting, apart from defining the temperament of people according to their birth date.</p>
<h3>Accuracy</h3>
<hr />
<p>Because the actual time it takes our Sun to reappear exactly in the same positions as seen from Earth is a little longer than 365 days (365.2421897 days), periodic adjustments are needed to keep an accumulation of the calendar\'s annual counts in alignment with Earth revolving around the sun.</p>
<p>The ancient Maya addressed this problem differently from what we do today. Instead of adding a leap year every 4 years, they subtracted 13 days every 52 years.</p>
<p>It is very interesting to know that the Haab\' calendar has an error of only 1 day in 6729 years, while our "modern" calendar has an error of only 1 day in 3236 years.</p>', '<p>K\'alendario solar maya, tunichil Haab, u chi\'bil 365 kin a katún le jun pa le tunich. U k\'alendario civil le maya u chikin, u k\'alendario sakbe\' le maya, le k\'alendario le reyes le maya.</p>
<p>U t\'aan "<strong>HAAB\'</strong>" ti\' le yukatek maya wíinik ti\' <strong>ch\'a\'aj</strong>.</p>
<p>Haab\' u ch\'a\'bil kaaj 18 ti\' ik\'al le ja\' u k\'aaba\', ka\' 5 k\'iin b\'a\'alche\'. K\'u\' u k\'iino\' 20 k\'iin ka\' 10 k\'iin, k-iik\'p\'ajal u uinal, le ja\' 360 k\'iin.</p>
<p>Le chikin ja\', ku 5 k\'iin kaaj, le wil kab\' wayeb. Le chikin ja\' ku suut u yuum 365 k\'iin.</p>
<p><strong>18 x 20 + 5 = 365 </strong></p>
<figure class="easyimage easyimage-full"><img alt="" src="../imgs/Calendario Haab/0.jpeg" width="300" /><figcaption></figcaption></figure>
<p>U junilo\'ob le ch\'a\'bil le maya u biino\' u yóok\'olil ti\' u paalen kaj, k\'íiwiko\'ob ti\' le ujelil u yo\'osal maíz u sak, u k\'úuntul, yéetel kuxtal sak lu\'umo\'ob tsakaj ti\' k\'íiwiko\'ob u tsolikil chíik\'al yuumo\'ob, le káajil u chéen yéetel u ts\'o\'okil tumen le wáayel kab le meyaj, bejo\'ol k\'íiwiko\'ob yéetel le ts\'o\'okil tumen le ajawo\'ob le maya.</p>
<p>Ti\' expertos, u k\'alendario k\'u ya\'ab tení ti\' yéetel le katún k\'iin ti\' invierno 550 ANE (Antes le Era Utsil), yéetel xooko\'obo\' ku núuch le chíik\'al u k\'áat u k\'u\'ukul le <strong>Tzolkin</strong>. Ti\' jun k\'a\'atil le Tzolkin yéetel le Haab\', ku k\'áaxal u bíino\'ob kaab le 52 ja\', ku ya\'ab ts\'oon u <strong>Rueda Calendárica</strong> ka ts\'aaj le <strong>Calendario Redondo</strong>, ku yéetel ti\' le maya, tsikbal le k\'ultúuras ti\' Mesoamérica.</p>
<h3>Tsilbil</h3>
<hr />
<p>U k\'alendario <strong>Haab\'</strong> ku yik\'áayi\' u k\'íiwiko\'ob ti\' u ki\'ik\'el ma\' jach tumen k\'íiwiko\'ob yéetel k\'úuntules tuunichilo\'ob ti\' u kuxtalil wáayilo\'ob yéetel le kajtal lu\'umil ka\'aj:</p>
<ul>
<li>Ch\'aajits\'íijil</li>
<li>Uk\'ijil</li>
</ul>
<p>Ku yik\'áayi\' u bejla\'e\' ts\'a\'ak tuunichilil yéetel u yo\'osalil wil lu\'umo\'ob, yéetel xan tsikbal u bejla\'e\'il no\'oj, u k\'ajlayil u no\'oj yóok\'ol k\'íiwik tsakaj.</p>
<h3>Bin k\'áak\'al</h3>
<hr />
<p>Tu ja\' chíik\'al le ts\'íib k\'iin wáy u kaab u wil lu\'umil tsikbal tuunichilo\'ob t\'aano\' ya\'abtuun wa\'íitil le ts\'íib k\'iin kaab u wil lu\'umil tsikbal tuunichilo\'ob u t\'áano\' ti\' wáay. U k\'u\'ultúuril maya, k\'atik noj kaaj túun ti\' ka\'achila\'alo\' u k\'abkunilo\'ob k\'iin k\'iin wáy, xooko\'obo\' ku wiik chúumukil kaaj tuunichilo\'ob k\'u wiik chúumukilo\'ob.</p>
<p>Le maya wíiniko\'ob ka\'achile\' táanil u t\'an chíik\'al le ch\'a\'bil Haab\' táan, tumeen le wíinik chi\' kiin j-pajal k\'abkunilo\'ob u tsikbal tuunichilo\'ob u t\'aano\' le ja\' tuunichilo\'ob tumen tsikbal tuunichilo\'ob tu ja\' ki\'in wáay.</p>
<p>U k\'alendario Haab', '<p>Ri q’ijob’äl rech ch’akul maya, xub’an pa ri Haab\', jun utz’ib’äl chi 365 q’ij chi xub’an k’aslem jun junab’ k’aslem chi junab’ pa ch’akul ri q’ijob’äl rech ri reyob’ Maya.</p>
<p>Ri saq tzij <strong>"HAAB\'"</strong> xub’an chi <strong>"JUNAB\'"</strong> pa ri saq tzij maya yucateco.</p>
<p>Ri Haab’ xub’an chike 18 k’ak’a’ taq 20 q’ij jun k’ak’a’, jun taq chike jun k’ak’a’ ri’ xub’an 5 q’ij. Jun k’ak’a’ taq 20 q’ij, xub’an pa uinal, xub’an chik jun ch’ob’äl. Ri e 18 k’ak’a’ chi jun chikaxik jun 360 q’ij.</p>
<p>Ri ruwi k’ak’a’, xub’an pa 5 q’ij, xub’an chi Wayeb. Ri’ xub’anik 19 k’ak’a’ xub’an 365 q’ij.</p>
<p><strong>18 x 20 + 5 = 365</strong></p>

<figure class="easyimage easyimage-full"><img alt="" src="../imgs/Calendario Haab/0.jpeg" width="300" />  <figcaption></figcaption>  </figure>
<p>Ri xub’an pa k’aslem chike ri k’aslem chi junab’ ri’ ri’ xub’an chi ruxq’a’ jun ch’o’wa’ jun, ri b’on, chike e ch’akul rech taq xuti’, chike ri k’ak’a’ ri k’aslem chi junab’ ri ya’ xub’an pa ri rutzil q’ij chi pa ch’akul rech e reyob’, rech taqik ri ch’ak q’ij ri junab’ chike jun ajaw jun na’oj.</p>
<p>Ri’ xub’an chike jun xb’an chi jun q’ij pa ri ya’ xub’an pa e cholta’ ch’akul xub’an chike ri rux b’elejeb’ saqi’ k’aslem ANE (Antes de Nuestra Era) chi jun xub’an pa jun b’e chike junb’il chike <strong>Tzolkin</strong>. Pa chi junab’ chike <strong>Haab\'</strong> chike <strong>Tzolkin</strong> xub’an junab’ chi jun chikaxik chike 52 junab’ xub’an pa jun saq tz’ij chi xub’an chi <strong>Rueda Calendárica</strong> chike <strong>Calendario Redondo</strong> ri xub’an chi xkiwach chi jun pa Mesoamérica chike jun ch’akul.</p>

<h3>Uwachib’il</h3>
<hr />
<p>Ri q’ijob’äl <strong>Haab\'</strong> xub’an chi jun taqib’äl rech junab’ chik chi jun chikaxik pa ri junab’ chike ri’ xub’an pa jun:</p>
<ul>
<li>Equinoccios</li>
<li>Solsticios</li>
</ul>
<p>Xub’an chike jun ub’ikib’il rech ri ajawib’ jun junab’ chike junab’ chik jun ch’ub’ chike jun junab’ rech taq xuti’ chike jun nab’eyal chike jun ch’ikub’ chi jun utz’ib’äl chik pa jun chikaxik ri k’aslem.</p>

<h3>K’aslem rech junab’</h3>
<hr />
<p>Rumal ri ya’ xub’an pa jun k’aslem rech q’ij ri xub’an pa q’ij pa ri jun k’aslem chi 365 q’ij (365.2421897 q’ij), xub’an jun q’ijob’äl chi junab’ chi jun chikaxik chi junab’ pa ch’akul ri xutux ri jun chikaxik pa junab’ chi jun k’aslem chike jun junab’ pa ch’akul chi ri’ xub’an chi jun junab’ pa junab’ chi xq’a jun q’ij chi junab’ chike ri xub’an pa jun junab’ chi jun chikaxik chi ri ch’akul chi jun junab’ chi xab’ jun junab’ chi xkaq’ej chi ri ch’akul pa jun junab’ 13 q’ij chi junab’ chi jun chikaxik chi 52 junab’.</p>

<p>Ri junab’ xub’an pa ri q’ijob’äl Haab’ jun xkab’an pa jun q’ij 1 q’ij pa junab’ 6729 junab’, ri junab’ xub’an pa jun q’ijob’äl <em>moderno</em> jun xkab’an pa jun q’ij 1 q’ij pa 3236 junab’.</p>
', '<p>Le calendario solar maya, ku t\'aano\'ob Haab\', es jump\'éel cuenta de 365 k’iino’ob yéetel bejo’ ku ya’abil tu ja’ab solar, es le calendario civil, agrícola maya, es le calendario le nojoch máak’ab Mayas.</p>    
<p>Le t\'aan <strong> "HAAB\'" </strong> ku t\'aano\'ob <strong> "AÑO" </strong> tu t\'aan maya yucateco.</p>    
<p>Le Haab’ ku ya’abil tu 18 meses de 20 k’iino’ob jump’éel, más jump’éel mes ku t’aan 5 k’iino’ob. Jump’éel mes de 20 k’iino’ob, ku t’aan uinal, ku ya’abil u propio t’aan. Le nojoch 18 meses ku ya’abil 360 k’iino’ob.</p>    
<p>Le último mes, ku ya’abil tu 5 k’iino’ob, ku t’aano’ob Wayeb. Le 19 meses tu ya’abil ku ts\'ook 365 k’iino’ob.</p>    
<p><strong>18 x 20 + 5 = 365 </strong></p>    
<p></p>    
<figure class="easyimage easyimage-full"><img alt="" src="../imgs/Calendario Haab/0.jpeg" width="300" />  
<figcaption></figcaption>  
</figure>    
<p>Fue elaborado por los astrónomos y matemáticos mayas para dar respuesta a la necesidad de las personas para su abastecimiento de alimento con la siembra y cosecha del sagrado maíz, el frijol, y toda clase de productos agrícolas indispensables para la buena alimentación del ser humano; y en la necesidad de establecer el tiempo de duración del mando y cambio de autoridades imperiales, comunales y civiles del pueblo.</p>    
<p>Este calendario, según los expertos, se estima que se utilizó por primera vez alrededor del solsticio de invierno de 550 ANE (Antes de Nuestra Era) y fue creado para ser utilizado en conjunto con el <strong> Tzolkin</strong>. En operación conjunta, el <strong> Haab</strong> y el <strong> Tzolkin</strong> crean un ciclo más grande de 52 años llamado la <strong>Rueda Calendárica</strong> o <strong>Calendario Redondo</strong> que fue utilizado no solo por los mayas sino también por el resto de las culturas en Mesoamérica.</p>    
<p></p>    
<h3>Utilidad</h3>    
<hr />  
<p>Le calendario <strong>Haab\'</strong> ku yáantaj ti’ le nojoch ka’analil yéetel le ka’analil tu ja’ab solar bey jump’éel:</p>    
<ul>  
<li>Equinoccios</li>  
<li>Solsticios</li>  
</ul>    
<p>Ku yáantaj xan ti’ le ka’analil ti’ jump’éel nojoch máak’ab le kaajo’ob, ku ya’abil le ritos ceremoniales nojoch yéetel le k’iino’ob para la siembra de cultivos, yéetel ku yáantaj le temperamento le máak’ab tu ja’ab u k’iino’obil le k’iino’obil u ya’abil.</p>    
<h3>Exactitud</h3>    
<hr />  
<p>Ti’ jump’éel k’iin ku ya’abil le nojoch ka’analil ku yant u K’iin tu ya’abil tu ya’ab nojoch posiciones ku ya’abil tu yóok’ol Nojoch Lu’um es un poco más largo que 365 k’iino’ob (365.2421897 k’iino’ob), ku ya’abil ajustes periódicos para mantener jump’éel nojoch cuenta le ja’abil le calendario tu ya’abil tu Nojoch Lu’um ximbal tu yóok’ol le K’iin.</p>    
<p>Le nojoch máak’ab mayas ku t’aan jump’éel jump’éel manera diferente ti’ le ku t’aan ti’ le k’iino’ob. En lugar de agregar jump’éel ja’ab bisiesto cada 4 ja’ab, restaron 13 k’iino’ob cada 52 ja’ab.</p>    
<p>Es muy interesante saber que le calendario Haab’ ku ya’abil jump’éel error de solo 1 k’iin tu 6729 ja’ab, bey jump’éel le calendario “moderno” ku ya’abil jump’éel error de solo 1 k’iin tu 3236 ja’ab.</p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (0, 'Informacion', 'Rueda Calendarica', 'Informacion', '<p>El nombre completo de cualquier fecha en el sistema de calendario maya consiste de una fecha Tzolk’in y una fecha Haab. La Rueda Calendárica es el entretejido de los calendarios Tzolk’in y Haab. En la Rueda Calendárica, una combinación del Tzolk’in y el Haab no se repetirán hasta que hayan pasado 52 períodos de 365 días. Esto está basado en el concepto matemático de “el mínimo común denominador” y “el mínimo común múltiplo”. Ambos números, 260 y 365, son divisibles por 5, y 260 dividido por 5 es igual a 52, mientras que 365 dividido por 5 es igual a 73. Por lo tanto, el mínimo común múltiplo de 260 y 365 es 5 x 52 x 73 = 18,980.</p><p>De este modo, la Rueda Calendárica es igual a 18,980 días, 52 x 365 o 52 años Haab. Los mayas creen que cuando una persona alcanza los 52 años de edad, ellos atienen la sabiduría especial de un anciano. Una fecha de la Rueda Calendárica, con componentes tanto del calendario Tzolk’in como el Haab, puede marcar de forma única un evento dentro de un período de 52 años. Sin embrago, cualquier evento que abarque más de 52 años requiere un calendario adicional, el calendario de Cuenta Larga.</p><img src="../img/ruedaCalendarica.gif" style="width: 100%"><p>El círculo más pequeño está conformado por 13 números; el círculo mediano por los 20 signos de los veinte días mayas del calendario Tzolkin, y el círculo más grande por el calendario haab con sus 365 días (dieciocho meses de veinte días y el mes corto de cinco días). En este conteo, los mayas consideraban que el día de la creación fue el 4 ahau 8 cumkú.</p><p>Cada cíclo de 18.980 días equivale a 52 vueltas del haab (calendario solar de 365 kines) y a 73 vueltas del tzolkin (calendario sagrado de 260 kines), y al término ambos vuelven al mismo punto. Cada 52 vueltas del haab se celebraba la ceremonia del fuego nuevo, analógicamente era un "siglo maya".</p>', '<p>The complete name of any date in the Maya calendar system consists of a Tzolk’in date and a Haab date. The Calendar Round is the interweaving of the Tzolk’in and Haab calendars. In the Calendar Round, a combination of the Tzolk’in and the Haab will not repeat until 52 periods of 365 days have passed. This is based on the mathematical concept of "the least common denominator" and "the least common multiple". Both numbers, 260 and 365, are divisible by 5, and 260 divided by 5 equals 52, while 365 divided by 5 equals 73. Therefore, the least common multiple of 260 and 365 is 5 x 52 x 73 = 18,980.</p>

<p>Thus, the Calendar Round is equal to 18,980 days, 52 x 365 or 52 Haab years. The Maya believe that when a person reaches 52 years of age, they attain the special wisdom of an elder. A date from the Calendar Round, with components of both the Tzolk’in and the Haab calendar, can uniquely mark an event within a 52-year period. However, any event spanning more than 52 years requires an additional calendar, the Long Count calendar.</p>

<img src="../img/ruedaCalendarica.gif" style="width: 100%" />

<p>The smallest circle is composed of 13 numbers; the medium circle by the 20 signs of the twenty Maya days of the Tzolkin calendar, and the largest circle by the Haab calendar with its 365 days (eighteen months of twenty days and the short month of five days). In this count, the Maya considered that the day of creation was 4 ahau 8 cumkú.</p>

<p>Each cycle of 18,980 days is equivalent to 52 turns of the Haab (365-day solar calendar) and 73 turns of the Tzolkin (260-day sacred calendar), and at the end, both return to the same point. Every 52 turns of the Haab, the ceremony of the New Fire was celebrated, analogously it was a "Maya century".</p>', '<p>Ti xaqachal ri nawal chi ri winäq ri maya, kach’ij pa k’iche’, xkanarik xolotaj wi na kawok K’iche’. Chich’an chi atinamit pa chuchqaj wi’, xk’utaj winaq pa chuwachab’, kiq’achawaj, xk’utaj winaq kitz’alaj chi xkik’ajol winaqab’, kiq’achawaj nawal chuwachab’. Chi xkinanok ri tzij pa chikam winaqil, yumi’ chikeje wi’ chiri k’ut chicach chi naj, kiwäch chi nawal kitzij winaq. Kutzij k’ut nawal kitzij chwäch chi nuk’uj.</p>

<p>Xkanarik xolotaj xk’aslemal kawo’ Pa chuwachab’ ri nahualil ri winäq, xkik’ajol winaq kiq’achawaj, xk’utaj winaq xq’aje’ chi ri uk’u’x winaq pa nawal kitzij winaq chi wachaj wi’ chiri k’ut chicach, kiq’achawaj xpe nawal chi ri winäqil xq’axikab’. Chuchqaj winaq chwäch chi winäqil, xk’utaj winaq xk’utaj nawal kiq’achawaj, yumi’ xkik’ajol winaq xkinanok ri k’ut kitzij winaq, yumi’ xkik’ajol kitzij chwäch chi nuk’uj, yumi’ xk’utaj kitzij winaq chi k’ut chwäch chi chuwachab’ chi winäqil. Xk’utaj kitzij winaq chi kawok wi’ chiri chwäch chi nawal kitzij winaq chuwachab’.</p>

<p>Xwakamiq’ij winaq k’iche’ xkawok k’iche’, xkanarik xolotaj xkik’ajol winaq chi quixkamab’ej nab’ey k’ut, xk’utaj winaq xpe kitzij k’ut chi nawal k’iche’ chi kib’ey, xkanarik xolotaj xkinanok ri nawal kitzij winaq chuwachab’ ri chuwachab’ chi quixkamab’ej nab’ey. Xpe winaq k’ut kawok k’iche’ xkik’ajol nawal chwäch chi chuwachab’ chiri k’ut chicach, xpe kitzij k’ut chi nawal kitzij winaq, yumi’ xk’utaj winaq chwäch chi nuk’uj, yumi’ xkinanok winaq chwäch chi k’ut, yumi’ xkinanok winaq chwäch chi quixkamab’ej nab’ey k’ut.</p>
', '<p>Ri saq b’i’ik ri taq q’ij pa jun utz’ib’äl rech jun q’ijob’äl maya xub’an chik jun q’ij Tzolk’in chike jun q’ij Haab’. Ri Rueda Calendárica xub’an jun chikawach ri q’ijob’äl Tzolk’in chike Haab’. Pa ri Rueda Calendárica, jun chiq’aq’ jun Tzolk’in chike jun Haab’ maj k’oyi chi jun chikaxik jun 52 taq q’ij junab’ taq 365 q’ij. Ri’ xub’an chi jun q’ij richin utz’ib’äl ri’ xub’an chik "jun chik q’ij richin ri’ jun chik xkalem" chike "jun chik xk’oy q’ij richin xkalem." E junab’ junab’ jun xkiwach 5, chike 260 k’a ch’ab’il chike 5 xa 52, xk’i 365 k’a ch’ab’il chike 5 xa 73. Ri’ xub’an chi jun chik xkalem richin jun 260 chike 365 jun 5 x 52 x 73 = 18,980.</p>

<p>Ri’ xub’an, ri Rueda Calendárica xub’an chi 18,980 q’ij, 52 x 365 chike 52 junab’ Haab’. Ri Maya xkiwach chi kaqal chi jun 52 junab’ chi jun ch’ab’il chi jun q’ij. Jun q’ij pa ri Rueda Calendárica, chike jun saq b’i’ik rech ri q’ijob’äl Tzolk’in chike ri Haab’, xub’an chi k’aslem jun q’aq’ jun 52 junab’. Xa jun q’aq’ xub’an chi jun 52 junab’ xub’an chi utz’ib’äl jun ch’akul, ri q’ijob’äl rech Utz’ib’äl Chik.</p>

<img src="../img/ruedaCalendarica.gif" style="width: 100%" />

<p>Ri jun xq’aq’ chi xub’an pa 13 nab’eyal; ri jun xq’aq’ chi xub’an 20 b’i’ik ri jun 20 q’ij ri q’ijob’äl Tzolk’in, chike ri jun xq’aq’ chiki ri q’ijob’äl Haab’ chike junab’ chi 365 q’ij (jun k’ak’a’ taq 20 q’ij chike jun k’ak’a’ chik pa 5 q’ij). Pa ri wachib’il, ri Maya xub’an chi jun q’ij pa ri xutz’ub’ chi jun 4 ahau 8 cumkú.</p>

<p>Jun chikaxik taq 18,980 q’ij xub’an chi 52 junab’ ri haab’ (q’ijob’äl ch’akul rech 365 q’ij) chike 73 junab’ ri tzolk’in (q’ijob’äl ch’ab’il rech 260 q’ij), chi xk’oyi k’a jun chi jun chikaxik jun q’ij. Jun chi 52 junab’ ri haab’ xub’an jun jun q’aq’ chi junab’ ri q’aq’ nuevo, xuquje’ xub’an jun "siglo maya."
</p>
', '<p>Le t\'aan completo tu jump\'éel k’iin tu sistema calendario maya ku ya’abil tu jump’éel k’iin Tzolk’in yéetel
jump’éel k’iin Haab’. Le Rueda Calendárica es le nojoch máak’ab le calendarios Tzolk’in y Haab’. Tu le Rueda
Calendárica, jump’éel combinación le Tzolk’in y le Haab’ ma’ ku ts’ook hasta ku ya’abil 52 períodos
de 365 k’iino’ob. Le t’aan ku yáantaj tu concepto matemático de “le mínimo común denominador” y “le mínimo
común múltiplo”. Le ka’a números, 260 y 365, ku ya’abil divisibles por 5, yéetel 260 dividido por 5 ku ya’abil igual a 52, mientras 365 dividido por 5 ku ya’abil igual a 73. Bey, le mínimo común múltiplo de 260 y 365 es 5 x 52 x 73 = 18,980.</p>

<p>Tu bejil, le Rueda Calendárica ku ya’abil igual a 18,980 k’iino’ob, 52 x 365 o 52 ja’ab Haab’. Le máak’ab maya ku ya’abil ku ya’abil jump’éel 52 ja’ab yéetel ku ya’abil u ts’ookbilil u nojoch máako’ob. Jump’éel k’iin le Rueda Calendárica, ku ya’abil componentes le calendario Tzolk’in yéetel le Haab’, ku ya’abil ti’ jump’éel nojoch jump’éel evento tu jump’éel período de 52 ja’ab. Ba\'ale’, jump’éel evento ku ya’abil más de 52 ja’ab ku ya’abil jump’éel calendario adicional, le calendario de Cuenta Larga.</p>

<img src="../img/ruedaCalendarica.gif" style="width: 100%" />

<p>Le círculo más pequeño ku ya’abil tu 13 números; le círculo mediano ku ya’abil tu 20 signos le veinte k’iino’ob maya le calendario Tzolk’in, yéetel le círculo más grande ku ya’abil le calendario Haab’ ku 365 k’iino’ob (dieciocho meses le veinte k’iino’ob yéetel le mes mejen le cinco k’iino’ob). Tu le ts’ookil, le máak’ab maya ku ya’abil ku le k’iin le creación ku ya’abil le 4 ahau 8 cumkú.</p>

<p>Jump’éel ciclo de 18,980 k’iino’ob ku ya’abil igual a 52 vueltas le Haab’ (calendario solar de 365 kines) yéetel 73 vueltas le Tzolk’in (calendario nojoch le 260 kines), yéetel ku ya’abil le ts’ook ku ya’abil le mismo punto. Cada 52 vueltas le Haab’ ku ya’abil le ceremonia del nuevo fuego, ku ya’abil un "siglo maya".</p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (1, 'Kin', 'Calendario Haab', 'Elementos', '<p>La escritura maya era un sistema logosilábico cuyo significado es discutido. Los símbolos individuales ("glifos") podían representar bien una palabra (normalmente un morfema) o una sílaba; a decir verdad, el mismo glifo con frecuencia podía usarse de las dos formas.</p>    <figure class="easyimage easyimage-full"><img alt="" src="imgs/Kin/0.jpeg" width="300" />  <figcaption></figcaption>  </figure>    <p> </p>', '<p>Maya writing was a logosyllabic system whose meaning is debated. Individual symbols ("glyphs") could represent either a word (usually a morpheme) or a syllable; indeed, the same glyph could often be used in both ways.</p>
<figure class="easyimage easyimage-full"><img alt="" src="imgs/Kin/0.jpeg" width="300" /> <figcaption></figcaption> </figure>
<p> </p>', '<p>Ri riwächil maya xq’ijib’äl k’iche’, xkanarik xolotaj xkik’ajol winaq chi rutz’ij tz’ikin; rutz’ij tz’ikin xwäch’aj wi’ chiri k’ut chicach chi nawal kitzij winaq, xk’utaj winaq xk’utaj nawal chwäch chi nawal k’iche’, yumi’ xkik’ajol nawal chwäch chi chuwachab’ chiri k’ut chicach. </p>
<figure class="easyimage easyimage-full"><img alt="" src="imgs/Kin/0.jpeg" width="300" />  <figcaption></figcaption>  </figure>
<p> </p>', '<p>Ri utz’ib’äl maya xub’an jun sistema logosilábico ri jun k’aslem xaya utzib’ej. Ri junb’il saq b’i’ik ("glifos") xub’an chi jun chik richin ri jun saq b’i’ik (xaja jun morfema) o jun sílaba; pa k’aslem, ri jun chik saq b’i’ik xub’an chi jun richin ri chike jun chi xk’oyi taq ri jun b’i’ik.</p> 
<figure class="easyimage easyimage-full"><img alt="" src="imgs/Kin/0.jpeg" width="300" /> <figcaption></figcaption> </figure> 
<p> </p>
', '<p>Le ts\'íib maya ku ya\'abil jump\'éel sistema logosilábico le ku t\'aano\'ob ku ya\'abil discusiones. Le símbolos individuales ("glifos") ku ya\'abil representar jump\'éel t\'aan (tu láak\' le morfema) o jump\'éel sílaba; tu t\'aanil, le mismo glifo ku ya\'abil usarse jump\'éel bejil ku nojoch jump\'éel dos formas.</p>
<figure class="easyimage easyimage-full"><img alt="" src="imgs/Kin/0.jpeg" width="300" />
<figcaption></figcaption>
</figure>
<p></p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (1, 'Mecanismo', 'Rueda Calendarica', 'Informacion', '<h2>Mecanismo</h2>

<p>De la Rueda del Calendario, se dice que el ciclo de 52 años es más importante que el año.</p>

<p>Un ejemplo de fecha en la rueda calendárica, 8 Cauac 13 Zip, se referiría al octavo día de la trecena Cauac en el Tzolkin, que coincide con el día 13 de Zip en el Haab.</p>

<p>La diferencia entre los 52 años de 365 días cada uno y los 52 años de 360 días, es de 260 días exactamente; así se puede llevar el cálculo de sus coincidencias a través de ciclos de 260 días, ya que</p>

<ul>
	<li>18 980 = 73 x 260</li>
	<li>18 720 = 72 x 260</li>
	<li>5 256 = 72  x 73 = 9 x 584.​</li>
</ul>

<p>También debe ser tomado en cuenta que 13 x 360 = 18 x 260 = 4 680.</p>

<p> 	Es decir, si los 5 días de Uayeb\' son omitidos (como debe haber sido el caso en los orígenes del calendario), los períodos de 360 y de 260 días coincidirían después de, respectivamente, 13 y 18 ciclos (13 "años" de 360 días).</p>
	Cuatro de esos ciclos de 13 "años" abarcan 52 "años" de 360 días.
	Ahora, 52 veces esos 5 adicionales días de Wayeb\' resultan en exactamente uno más de los ciclos de 260 días.</p>
	<p>El sistema de la rueda calendárica, sirve para interpretar una sucesión infinita de períodos de 52 años. Se desconoce su nombre en lenguas mayenses, pero el nombre en idioma náhuatl utilizado por los mexicas era "Xiuhnelpilli", aunque es más usual encontrarlo escrito como Xiuhmolpilli, forma gramaticalmente incorrecta; cuyo significado es anudación de los años.</p>

	<p>Cada 52 años las culturas mesomericanas realizaban importantes ceremonias. Para el caso de los mexicas era la llamada "ceremonia del fuego nuevo".
</p>
', '<h2>Mechanism</h2>

<p>From the Calendar Wheel, it is said that the 52-year cycle is more important than the year.</p>

<p>An example of a date on the calendar wheel, 8 Cauac 13 Zip, would refer to the eighth day of the Cauac trecena in the Tzolkin, which coincides with the 13th day of Zip in the Haab.</p>

<p>The difference between the 52 years of 365 days each and the 52 years of 360 days is exactly 260 days; thus the calculation of their coincidences can be carried out through cycles of 260 days, since</p>

<ul>
    <li>18,980 = 73 x 260</li>
    <li>18,720 = 72 x 260</li>
    <li>5,256 = 72 x 73 = 9 x 584.</li>
</ul>

<p>It should also be noted that 13 x 360 = 18 x 260 = 4,680.</p>

<p>That is, if the 5 days of Uayeb\' are omitted (as must have been the case in the origins of the calendar), the periods of 360 and 260 days would coincide after, respectively, 13 and 18 cycles (13 "years" of 360 days).</p>
<p>Four of these cycles of 13 "years" encompass 52 "years" of 360 days. Now, 52 times those 5 additional days of Wayeb\' result in exactly one more cycle of 260 days.</p>

<p>The system of the calendar wheel serves to interpret an infinite succession of periods of 52 years. Its name in Mayan languages is unknown, but in the Nahuatl language used by the Mexicas it was called "Xiuhnelpilli," although it is more commonly written as Xiuhmolpilli, a grammatically incorrect form; which means bundling of years.</p>

<p>Every 52 years, the Mesoamerican cultures performed important ceremonies. In the case of the Mexicas, it was the so-called "ceremony of the new fire."</p>', '<h2>K’ut</h2>

<p>Chi k’oxajil Winaq’ ronojelaj 52 k’ajkunab’ chuqa ri le k’aj.</p>

<p>Umukajil che ri ajb’i Winaq’ ronojelaj, 8 Cauac 13 Zip, xkanarik xolotaj xkik’ajol wi’ chiri k’ut chicach ri c’i Winaq’ ronojelaj, chiwicha ri ajb’i 13 Zip ri c’i Winaq’ k’aj.</p>

<p>Chiri wi’ chi’ 52 ronojelaj winaq chuqa kitzij 365 k’ajkunab’, chiri wi’ 52 ronojelaj winaq chuqa kitzij 360 k’ajkunab’ chiwa’ 260 k’ajkunab’ chiwi’; chiqa kitzij ronojelaj winaq rutz’ij tz’ikin, chi’.</p>

<ul>
    <li>18,980 = 73 x 260</li>
    <li>18,720 = 72 x 260</li>
    <li>5,256 = 72 x 73 = 9 x 584.</li>
</ul>

<p>Ko’xaj kitzij q’atin ri 13 x 360 = 18 x 260 = 4,680.</p>

<p>Winaq chuwächik, chi ri 5 k’ajkunab’ re Uayeb’ chi’ xkib’aj ri q’atin k’aj kitzij q’atin, chi’.</p>

<p>Q’ati’ chuwächik ronojelaj winaq chuqa k’aj kitzij kitzij kitzij chuwächik kitzij re 52 chuwächik re xolabaj k’aj.</p>

<p>Tajin, 52 q’atin kitzij ri kitzij q’atin k’aj kitzij chuwächik kitzij kitzij kitzij kitzij chuwächik.</p>

<p>Yumi’ ri, 52 chuwächik kitzij ri 5 taqaj q’atin ri’i’ Wayeb’ chi’ xkib’aj ri q’atin k’aj kitzij q’atin.</p>

<p>Q’ati’ chuwächik ronojelaj winaq xkik’ajol wi’ chi’, xwäch’aj wi’ chi’ ri k’iche’ kitzij junan chi k’aj xik’in chi’, xwäch’aj wi’ chi’ ri k’iche’ kitzij junan chi kitzij q’atin winaq chi c’i, xkanarik xi’ q’atin xolabaj tz’ikin kitzij.</p>

<p>Ri c’i 52 chuwächik kitzij ronojelaj winaq, chuwächik winaq chiqa chuwächik q’atin wi’ junan. Chiri chi mexica\';', '<h2>Mecanismo</h2>

<p>Chi ri Rueda ri Q’ijob’äl, xub’an chi ri chikaxik taq 52 junab’ ri jun chik k’aslem chi junab’.</p>

<p>Jun ruwäch richin ri q’ij pa ri rueda calendárica, 8 Cauac 13 Zip, xub’an chi ri ruwäch q’ij pa ri trecena Cauac pa ri Tzolkin, ri jun chik ri xel 13 pa Zip pa ri Haab.</p>

<p>Ri xub’an chi jun chik pa ri 52 junab’ ri 365 q’ij chi ri 52 junab’ ri 360 q’ij, xub’an chi 260 q’ij taq pa ri; chi ke ri xub’an chi jun chik richin ri xka’iqil chi e pa junab’ ri 260 q’ij, chi ke:</p>

<ul>
<li>18 980 = 73 x 260</li>
<li>18 720 = 72 x 260</li>
<li>5 256 = 72 x 73 = 9 x 584</li>
</ul>

<p>Xujunila chi jun chik xub’an chi 13 x 360 = 18 x 260 = 4 680.</p>

<p>Ri xub’an chi, chi ri ri 5 q’ij ri Uayeb’ xub’an chi jun saq b’i’ik (chi jun chiq ri jun chik pa ri q’ijob’äl), ri chikaxik taq 360 chi 260 q’ij xub’an chi jun jun chi, respectivamente, 13 chi 18 chikaxik (13 "junab’" ri 360 q’ij).</p>
<p>Ri ri’, ri 4 ri jun chik chi 13 "junab’" xub’an chi 52 "junab’" ri 360 q’ij. Ri xub’an chi 52 xujunila ri 5 q’ij ri Wayeb’ xub’an chi jun chik chi 260 q’ij.</p>
<p>Ri sistema ri rueda calendárica xub’an chi jun jun saq b’i’ik richin jun chik pa jun chikaxik taq 52 junab’. Xaya saq b’i’ik pa ri k’iy taq chi maya’, chi ri k’iy pa ri náhuatl xub’an chi xiuhnelpilli, xub’an jun chik chi xiuhmolpilli, xub’an chi jun k’aslem richin ri anudación ri junab’.</p>

<p>Ri 52 junab’ xub’an chi jun k’aslem taq saq ch’akul. Chi ri mexicas xub’an chi chi ruwäch "ceremonia del fuego nuevo".</p>
', '<h2>Mecanismo</h2>

<p>Tu Rueda del Calendario, ku t’aano’ob que le ciclo de 52 ja’ab es ma’ importante que le ja’ab.</p>

<p>Jump’éel ejemplo de k’iin tu rueda calendárica, 8 Cauac 13 Zip, ku ya’abil ku tsikbal le octavo k’iin de la trecena Cauac tu Tzolkin, le ku ts’ook ku jump’éel k’iin 13 de Zip tu Haab.</p>

<p>Le diferencia entre le 52 ja’ab de 365 k’iino’ob yéetel le 52 ja’ab de 360 k’iino’ob, es de 260 k’iino’ob exactamente; beyo’ ku ya’abil ku xook le nojoch u ya’abil u coincidencias tu ciclos de 260 k’iino’ob, ya’ax ku ya’abil:</p>

<ul>
<li>18,980 = 73 x 260</li>
<li>18,720 = 72 x 260</li>
<li>5,256 = 72 x 73 = 9 x 584</li>
</ul>

<p>Bey xan ku ya’abil ku yaantal tu cuenta que 13 x 360 = 18 x 260 = 4,680.</p>

<p>Es t’aan, si le 5 k’iino’ob de Uayeb’ ku omitidos (como ku ya’abil le caso tu los orígenes del calendario), le períodos de 360 y de 260 k’iino’ob ku ya’abil después de, respectivamente, 13 y 18 ciclos (13 "ja’ab" de 360 k’iino’ob).</p>

<p>Kuatro de le ciclos de 13 "ja’ab" ku ya’abil 52 "ja’ab" de 360 k’iino’ob.
Ahora, 52 veces le 5 k’iino’ob adicionales de Wayeb’ ku ya’abil tu exactamente jump’éel más de le ciclos de 260 k’iino’ob.</p>

<p>Le sistema de le rueda calendárica, ku ya’abil ku t’aan jump’éel nojoch suceso de períodos de 52 ja’ab. Ku t’aan ku ya’abil su t’aan tu t’aan mayenses, ba’ale’ le t’aan tu t’aan náhuatl ku ya’abil por le mexicas ku "Xiuhnelpilli", ba’ale’ es ma’ usual ku ya’abil ku yaan escrito como Xiuhmolpilli, forma gramaticalmente incorrecta; le significado es anudación de los ja’ab.</p>

<p>Cada 52 ja’ab le culturas mesomericanas ku ya’abil importantes ceremonias. Ti’ le caso de los mexicas es la llamada "ceremonia del fuego nuevo".</p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (1, 'Nahual', 'Calendario Cholquij', 'Elementos', '<p>Nahual, también llamado <strong>nagual</strong> o <strong>nawal​</strong> (en náhuatl: nahualli ‘oculto, escondido, disfraz’), dentro de las creencias mesoamericanas, es una especie de brujo o ser sobrenatural que tiene la capacidad de tomar forma animal. El término refiere tanto a la persona que tiene esa capacidad como al animal mismo que hace las veces de su alter ego o animal tutelar.

<p>De acuerdo con la tradición y cosmovisión de los pueblos Mesoamericanos los Nahuales son espíritus y energías protectoras que acompañan a todos los elementos de la naturaleza, incluyendo a los humanos y animales a lo largo de toda su existencia.</p>

<p>Para la civilización Maya el nahual de cada persona era de suma importancia. Era algo que todos debían conocer y aprender a manejarlo. Debían saber cuándo se fue engendrado, la fecha de nacimiento, el año, la energía que le protege y su misión.</p>

<p>Dentro de la cultura maya se dice que cada uno está relacionado con un animal  que es quién le dirige, como un ángel guardián, alguien con quien se identifica, con quien se encuentra conectado espiritualmente. Se dice también que cada persona incluso nace con el espíritu de un animal, y este se encarga de protegerlo y guiarlo.</p>

<h2 class="text-center"> conoce los nahuales:</h2>
<img alt="" src="../img/DiasMayas1.jpg"/>', '<p>Nahual, also called <strong>nagual</strong> or <strong>nawal</strong> (in Nahuatl: nahualli \'hidden, concealed, disguised\'), within Mesoamerican beliefs, is a kind of sorcerer or supernatural being that has the ability to take animal form. The term refers both to the person who has that ability and to the animal itself that serves as their alter ego or tutelary animal.</p>

<p>According to the tradition and worldview of Mesoamerican peoples, Nahuales are protective spirits and energies that accompany all elements of nature, including humans and animals throughout their existence.</p>

<p>For the Maya civilization, the nahual of each person was of utmost importance. It was something that everyone should know and learn to handle. They needed to know when they were conceived, their date of birth, the year, the energy that protects them, and their mission.</p>

<p>Within Mayan culture, it is said that each person is related to an animal that guides them, like a guardian angel, someone they identify with, with whom they are spiritually connected. It is also said that each person is even born with the spirit of an animal, and this spirit is responsible for protecting and guiding them.</p>

<h2>Meet the nahuales:</h2>
<img alt="" src="../img/DiasMayas1.jpg"/>
', '<p>Nahual, ronojel k\'iche\' nahualli \'sobrevivir, k\'ajolil, ronojel\' (chi\' náhuatl: nahualli \'tajak, tajak, tajak\'), wi\' jun chimalaj tz\'ikin uta ronohel matalaj chik, nimat xk\'utij ti ri nahual. Wi\' xu\'na\'ab\' wi\' k\'utinon kib\'ajil achi wi\' k\'iche\' uk\'uxaj awach matalaj jun ajmaqik tu\'bil achi tu\'bil nuk\'ayaj.</p>

<p>Xek\'onojel uk\'uxa\' ki\'wikalajaj achi ajuach ki\'wi\' ri uk\'uxa\' xik\'al wi\' chik, ki\'wi\' uk\'uxa\'xik\'alil k\'ajolilejil chi kaj chuunil ronojelajil k\'iche\', k\'ajol, u yax b\'antaj ta xk\'utij awachilaj.</p>

<p>Ta chi k\'iche\' k\'ajol, xu\'na\'ab\' wi\' tz\'akb\'aliwi\' achi uk\'uxa\' chik\'alil ut achi k\'iche\' chi ta\' wach kib\'ajil, ri winaq chik ri tu\'bil, ri k\'ajol, achi ri uk\'uxa\' xik\'alil k\'ajol chik ri wi\' chik\'alilejil. Ta wi\' chik ri k\'utinon awach wi\' k\'iche\' chik\'ajil, achi ta ri ajmaqik ronohel ruk\' ri awach xk\'utij ta ronohel uta xk\'utijil.</p>

<h2> Tunajel ri nahual:</h2>
<img alt="" src="../img/DiasMayas1.jpg"/>', '<p>Nahual, xub’an chik ri <strong>nagual</strong> chi <strong>nawal</strong> (pa ri náhuatl: nahualli \'oculto, escondido, disfraz\'), xub’an chi ri k’aslem ri nahuales mesoamericanos, chi ri junab’ saq ch’akul chi chi ri chiwäch chike chi chiwi\' chik ri aqi\' pa ri chikop, chiwäch xub’an chi ri jun chik ri chi k\'utk\'axik chik ri q\'ij ri laq\' taq ri ri kaj wi. 

<p>Taq saq xcha\'ib\'al chi ri tradición y cosmovisión ri ri chikop Mesoamericanos ri Nahuales wi saq ch’akul ri ri chikop ri chi ri rutz\'ib\'äl, ki\' ri saq k\'o ri chirutz\'ib\'äl chike, xub\'an chi ri chiwi\' chik chik ch\'akul rutz\'ib\'äl k\'utk\'axik ri q\'ij ri lalaki\' ri chirutz\'ib\'äl k\'i\'.</p>

<p>Chi ri chiwäch Maya wi ri nahual pa ri wi\' ki\'xik chike wi. Ri xka\'it ri wi\' chike aq\'ijik ri ri chik q\'ij, ri b\'i\'ik, ri rutz\'ib\'äl chike chirutz\'ib\'äl k\'utk\'axik ri chik ri q\'ij.</p>

<p>Chi ri chirutz\'ib\'äl maya xub\'an chi ri chik chike ri jun k\'o taq k\'i\' ri chiwäch chike, xub\'an chik ri chikop chirutz\'ib\'äl, chib\'an q\'ij chikop taq ri q\'ij k\'utk\'axik ri junab\', yul pa taqib\'äl chirutz\'ib\'äl k\'utk\'axik.</p>

<h2>Conoce ri nahuales:</h2>
<img alt="" src="../img/DiasMayas1.jpg"/>
', '<p>Nahual, bey xan ku t’aano’ob <strong>nagual</strong> o <strong>nawal</strong> (tu náhuatl: nahualli ‘oculto, escondido, disfraz’), tu le kuxtal ku ya’abil mesoamericanas, ku ya’abil jump’éel máak’ o máak’ nojoch le ku ya’abil u k’áat ku ya’abil forma le ba’al. Le t’aan ku t’aano’ob tanto tu jump’éel máak’ ku ya’abil le k’áat como tu ba’al ku ya’abil jump’éel alter ego o ba’al tutelar.</p>

<p>Tu yáantaj ku t’aano’ob yéetel le cosmovisión le máak’ob Mesoamericanos le Nahuales ku ya’abil pixano’ob yéetel yáantajo’ob nojoch ku ya’abil tu yáaxil jump’éel le ba’alilo’ob le yaan yéetel le máak’ob yéetel ba’alo’ob tu ts\'ook u kuxtal.</p>

<p>Tu le kuxtal Maya le nahual tu jump’éel máak’ ku ya’abil nojoch importancia. Ku ya’abil jump’éel ba’ax ku yaan u t’aan yéetel ku ts’o’okol ku ya’abil. Ku ya’abil ku ya’abil jump’éel ka’anal yéetel ku ya’abil. Ku ya’abil ku ya’abil ku ya’abil jump’éel u k’iin le ya’abil, le k’iin u ya’abil, le ja’ab, le yáantaj ku ya’abil yéetel le misión ku ya’abil.</p>

<p>Tu le kuxtal maya ku t’aano’ob ku ya’abil jump’éel tu ka’anal yéetel jump’éel ba’al ku yaan ku ku ya’abil, bey jump’éel ángel guardián, ku máako’ob ku ya’abil ku t’aano’ob, ku ya’abil ku ya’abil nojoch yéetel tu pixanil. Ku t’aano’ob xan ku jump’éel máak’ incluso ku ya’abil tu pixan le jump’éel ba’al, yéetel le ba’al ku ya’abil u ya’abil yéetel ku ya’abil ku ya’abil.</p>

<h2> conoce los nahuales:</h2>
<img alt="" src="../img/DiasMayas1.jpg"/>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (3, 'Uayeb', 'Calendario Haab', 'Elementos', '<p>Los últimos cinco días del ciclo de Haab son el mes 19, llamado Uayeb. Estos son días impredecibles, no para planificar eventos importantes o viajar fuera de casa.</p>', '<p>The last five days of the Haab cycle are the 19th month, called Uayeb. These are unpredictable days, not suitable for planning important events or traveling away from home.</p>
', '<p>Ri\' uk\'uxaj taq k\'ajol Haab, u chwe\'n taq uq\'ij u chiwech, uq\'ij 19, achi\' Uayeb. Uq\'ij chiwech, chik\'alilab\'al chiwi\' chiwinaqil achi chiwi\' k\'utinonal achi chitinaqutinonal chukuchaq k\'ajol chi wi\' aj k\'utij chiwinaq.</p>
', '<p>Jun winaq taq ri xkib’aal ri b’i’ik ri Wajxaqib’ B’atz’ wi’ ri kinab’ 19, chi’iq Uayeb. Ri chikop ulew utz k’ayb’al chi winaq, chi uch’ux uwäch, xub’an chi ri chiwäch chi k’alaj ri chikop k’ayb’al chik ri junab’.</p>
', '<p>Le últimos cinco k’iino’ob le ciclo de Haab ku ya’abil le mes 19, ku t’aano’ob Uayeb. Le yáax k’iino’ob ma’ ya’abil ku ya’abil, ma’ ku ya’abil jump’éel eventos importantes o ku ya’abil xíimbal fuera de naj.</p>
');
INSERT INTO tiempomaya.pagina (orden, nombre, categoria, seccion, htmlCodigo, htmlCodigo_en, htmlCodigo_qu, htmlCodigo_kq, htmlCodigo_yu) VALUES (2, 'Uinal', 'Calendario Haab', 'Elementos', '<p>El uinal se puede ver como el equivalente a nuestros meses ya que constan de 20 días, pero en lugar de 12 de ellos, el calendario Haab Maya cuenta con 18 de ellos. Los uinales, a parte de contar el tiempo se utilizaban para realizar ciertas actividades.</p>', '<p>The uinal can be seen as the equivalent of our months since they consist of 20 days, but instead of 12 of them, the Maya Haab calendar has 18 of them. The uinals, apart from counting time, were used to carry out certain activities.</p>', '<p>Uk\'uxaj chiwech uq\'ij uchiwech, ri k\'utinonal k\'ut, k\'u k\'ut b\'anoj, u k\'utinonal Haab Maya, ri k\'utinonal Uinal ruk\'uxaj chiwech. Ri k\'utinonal uinal, chi k\'utinonal chik\'utij uq\'ij chi k\'u k\'ut, chik\'alilab\'al chiwi\' wi\' uchwiwinaq, uchik\'otinonal.</p>', '<p>El uinal chi\'ik utz k’ayb’al chik ri chikop uwäch chi ri k’o’ob ri k’ajol, pa junab’ utz k’ayb’al, chi junab’ uch’ux, xub’an chi ri calendero Haab Maya chik ri winaq 18. Ri uinales, chi’iq ri k’o’ob, xub’an chi ri junwinaq ri ch’uti’ taq utz k’ayb’al chi chikop ulew ri ri ri’ chiwäch.</p>
', '<p>Le uinal ku ya’abil ku jump’éel equivalente tu le k’iino’ob le kuxtal ya que ku ya’abil tu 20 k’iino’ob, ba’ale’ tu lugar le 12 le’elo’ob, le calendario Haab Maya ku ya’abil ku 18 le’elo’ob. Le uinalo’ob, aparte de contar le k’iin ku ya’abil para realizar ciertas actividades.</p>
');
